import { createWorker } from 'tesseract.js';
import { DocumentConverter } from 'docling.rs';
import { ExtractedField } from '@pramaan/contracts';

const THRESHOLD = 0.90;

export interface RunRequest {
  image: string;
  domain: "bill" | "lease";
}

export async function read(req: RunRequest): Promise<ExtractedField[]> {
  const results: ExtractedField[] = [];

  try {
    if (!req.image || req.image.trim() === '') {
      return [];
    }

    const isPdf = req.image.toLowerCase().endsWith('.pdf') || req.image.startsWith('data:application/pdf');

    if (isPdf) {
      // 1. Use Docling for PDFs via docling.rs native bindings
      const converter = new DocumentConverter();
      
      // Decode base64 input (handles raw base64 or data URIs)
      const base64Data = req.image.includes(',') ? req.image.split(',')[1] : req.image;
      const buffer = Buffer.from(base64Data, 'base64');

      const docResult = await converter.convertAsync({
        name: 'document.pdf',
        data: buffer,
        format: 'pdf'
      }, { to: 'json' });

      if (docResult.status === 'failure') return [];

      const doc = JSON.parse(docResult.content);

      // Recursive function to extract TextItems
      const extractTextItems = (node: any) => {
        if (node.text && typeof node.text === 'string') {
          const prov = node.prov?.[0]; // Get the first provenance item for bounding box
          if (prov && prov.bbox) {
            const bbox = prov.bbox;
            results.push(parseField(
              node.text,
              [bbox.l, bbox.t, bbox.r - bbox.l, bbox.b - bbox.t],
              1.0 // Confidence defaults to 1.0 since it's a PDF text layer
            ));
          }
        }
        if (node.children && Array.isArray(node.children)) {
          for (const child of node.children) {
            extractTextItems(child);
          }
        }
      };

      // Extract regular text blocks
      if (doc.main_text) {
        for (const item of doc.main_text) {
          extractTextItems(item);
        }
      }

      // 7. Handle tables specifically for line items
      if (doc.tables) {
        for (const table of doc.tables) {
          if (table.data) {
            for (const row of table.data) {
              for (const cell of row) {
                if (cell.text && cell.bbox) {
                  results.push(parseField(
                    cell.text,
                    [cell.bbox.l, cell.bbox.t, cell.bbox.r - cell.bbox.l, cell.bbox.b - cell.bbox.t],
                    1.0
                  ));
                }
              }
            }
          }
        }
      }

    } else {
      // 1. Fall back to Tesseract.js for Images
      const worker = await createWorker('eng');
      try {
        const { data } = await worker.recognize(req.image);
        
        if (data && data.blocks) {
          // Extract word-level data as requested by traversing the document hierarchy
          for (const block of data.blocks) {
            for (const paragraph of block.paragraphs) {
              for (const line of paragraph.lines) {
                for (const word of line.words) {
                  const x = word.bbox.x0;
                  const y = word.bbox.y0;
                  const width = word.bbox.x1 - word.bbox.x0;
                  const height = word.bbox.y1 - word.bbox.y0;
                  
                  results.push(parseField(
                    word.text.trim(),
                    [x, y, width, height],
                    word.confidence / 100.0 // Normalize 0-100 to 0.0-1.0
                  ));
                }
              }
            }
          }
        }
      } finally {
        await worker.terminate();
      }
    }
  } catch (error) {
    console.error("OCR Pipeline failed gracefully:", error);
    // 6. Return empty array on failure, do not crash
    return [];
  }

  return results;

}

function parseField(text: string, bbox: [number, number, number, number], conf: number): ExtractedField {
  // 2. Parse out a numeric value if present
  let value: number | null = null;
  const numMatch = text.match(/-?[\d,]+(\.\d+)?/);

  
  if (numMatch) {
    const parsed = parseFloat(numMatch[0].replace(/,/g, ''));
    if (!isNaN(parsed)) {
      value = parsed;
    }
  }

  // 2. Parse out unit string if present (e.g. "per tablet")
  let unit: string | null = null;
  const unitMatch = text.match(/\b(per\s+[a-zA-Z]+)\b/i);
  if (unitMatch) {
    unit = unitMatch[1].toLowerCase();
  }

  // 3 & 4. Confidence and low_conf flag
  return {
    text,
    value,
    unit,
    bbox,
    confidence: conf,
    low_conf: conf < THRESHOLD
  };
}
